INSERT INTO `samples` VALUES (221, 3, 'MY-CS-2024-4005', 'Shopee', '2024-11-20 11:35:18', '我的货坏了！包装都破了。', 'Barang sy rosak! Box pecah.', 'Barang saya rosak! Box pecah.', '[\"box\"]', '[\"投诉货损\"]', 'angry', 'after-sales', 'Colloquial', 1, '{\"sy\": \"saya\"}', '2026-02-22 22:46:47');
INSERT INTO `samples` VALUES (222, 3, 'MY-CS-2024-4006', 'Lazada', '2024-11-20 11:40:33', '快递员态度很差，不给我打电话。', 'Courier attitude teruk, x call sy.', 'Courier attitude teruk, tak call saya.', '[\"courier\", \"attitude\", \"call\"]', '[\"投诉快递员态度\"]', 'negative', 'after-sales', 'Colloquial', 1, '{\"x\": \"tak\", \"sy\": \"saya\"}', '2026-02-22 22:46:47');
INSERT INTO `samples` VALUES (223, 3, 'MY-CS-2024-4007', 'TikTok', '2024-11-20 11:45:27', '我的快递卡在一个地方好几天了，都不动！', 'Tracking stuck kat satu tempat berapa hari, x bergerak!', 'Tracking stuck kat satu tempat berapa hari, tak bergerak!', '[\"tracking\", \"stuck\"]', '[\"投诉物流停滞\"]', 'negative', 'after-sales', 'Colloquial', 1, '{\"x\": \"tak\"}', '2026-02-22 22:46:47');
