INSERT INTO `samples` VALUES (227, 3, 'MY-CS-2024-4011', 'TikTok', '2024-11-20 12:05:36', '快递员不打电话就放在门卫那里，东西被偷了！', 'Courier x call terus letak guardhouse, barang curi!', 'Courier tak call terus letak guardhouse, barang curi!', '[\"courier\", \"call\", \"guardhouse\"]', '[\"投诉快递员\"]', 'angry', 'after-sales', 'Colloquial', 1, '{\"x\": \"tak\"}', '2026-02-22 22:46:47');
